#!/usr/bin/env node
// Inventory of generated files in source control. Fails when a generated file
// is tracked (or about to be added) outside the allowlist in
// repo-check.config.json, when a build output is tracked at all, and when
// .gitignore would hide an allowlisted generated file or stop ignoring a build
// output. See docs/GENERATED_FILES_POLICY.md.
//
// Usage: node scripts/repo/check-generated-files.mjs

import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { gitLsFiles, matchesAny } from "../docs/markdown.mjs";
import { readRepoConfig } from "./config.mjs";

function hasMarker(root, file, markers, lines) {
  let head;
  try {
    head = fs.readFileSync(path.join(root, file)).subarray(0, 4096);
  } catch {
    return false;
  }
  // Binary files carry no marker comments.
  if (head.includes(0)) return false;
  const text = head.toString("utf8").split(/\r?\n/).slice(0, lines).join("\n");
  return markers.some((marker) => text.includes(marker));
}

function emittedSource(file, emitted, present) {
  for (const { generated, source } of emitted) {
    if (!file.endsWith(generated)) continue;
    const candidate = file.slice(0, -generated.length) + source;
    if (candidate !== file && present.has(candidate)) return candidate;
  }
  return null;
}

const DELETE = "delete it and keep it ignored";
const ALLOWLIST =
  "delete it, or add it to generatedFiles.tracked in scripts/repo/repo-check.config.json and the policy";

/**
 * Classify one path. Returns null for authored files, otherwise
 * { class, allowed, why, remedy } for the generated class it belongs to.
 */
export function classify(file, config, { present, isMarked }) {
  const build = config.buildOutputs.find((c) => matchesAny(file, c.detect));
  if (build) {
    return {
      class: build.class,
      allowed: false,
      why: `build output of ${build.generator}`,
      remedy: DELETE,
    };
  }
  const tracked = config.tracked.find((c) => matchesAny(file, c.detect));
  if (tracked) {
    return {
      class: tracked.class,
      allowed: matchesAny(file, tracked.allow),
      why: `generated by ${tracked.generator}`,
      remedy: ALLOWLIST,
    };
  }
  const source = emittedSource(file, config.emitted, present);
  if (source) {
    return {
      class: "emitted-from-typescript",
      allowed: false,
      why: `compiled from ${source}`,
      remedy: DELETE,
    };
  }
  if (isMarked(file)) {
    const allowed = config.tracked.some((c) => matchesAny(file, c.allow));
    return {
      class: "marked-generated",
      allowed,
      why: "carries a generated-file marker",
      remedy: ALLOWLIST,
    };
  }
  return null;
}

function checkIgnored(root, paths) {
  if (paths.length === 0) return new Set();
  const result = spawnSync(
    "git",
    ["check-ignore", "--no-index", "--stdin", "-z"],
    {
      cwd: root,
      input: paths.join("\0") + "\0",
      encoding: "utf8",
    }
  );
  return new Set(result.stdout.split("\0").filter(Boolean));
}

/** Return a sorted list of human-readable problems; empty means clean. */
export function checkGeneratedFiles(
  root,
  config,
  files = gitLsFiles(root, ["."])
) {
  const problems = [];
  const present = new Set(files);
  const isMarked = (file) =>
    hasMarker(root, file, config.markers, config.markerLines);

  for (const file of files) {
    const verdict = classify(file, config, { present, isMarked });
    if (!verdict || verdict.allowed) continue;
    problems.push(
      `${file}: ${verdict.class} (${verdict.why}) is not allowed in source control; ${verdict.remedy}`
    );
  }

  // Allowlisted generated files and authored files must stay visible to Git:
  // a blanket ignore rule would let `git clean -X` or a fresh checkout drop them.
  const ignoredTracked = checkIgnored(root, files);
  for (const file of files.filter((f) => ignoredTracked.has(f))) {
    problems.push(
      `${file}: tracked file is matched by .gitignore; narrow the ignore rule`
    );
  }

  const probes = config.buildOutputs.flatMap((c) =>
    c.probes.map((probe) => ({ probe, c }))
  );
  const ignoredProbes = checkIgnored(
    root,
    probes.map((p) => p.probe)
  );
  for (const { probe, c } of probes) {
    if (!ignoredProbes.has(probe)) {
      problems.push(`.gitignore: ${c.class} output "${probe}" is not ignored`);
    }
  }

  return problems.sort();
}

function main() {
  const root = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    "../.."
  );
  const config = readRepoConfig(root).generatedFiles;
  const problems = checkGeneratedFiles(root, config);
  for (const problem of problems) console.error(problem);
  if (problems.length > 0) {
    console.error(
      `\n${problems.length} generated-file problem(s). See ${config.policy}.`
    );
    process.exit(1);
  }
  console.log(
    "Generated files: OK (only allowlisted generated files are tracked)."
  );
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) main();
